CREATE TABLE `system_feature_flags` (`id` BIGINT UNSIGNED NOT NULL AUTO_INCREMENT, `uuid` CHAR(36) NOT NULL, `key` VARCHAR(160) NOT NULL, `environment` VARCHAR(32) NOT NULL, `description` VARCHAR(500) NULL, `enabled` BOOLEAN NOT NULL DEFAULT false, `rollout_percentage` INT NOT NULL DEFAULT 100, `metadata` JSON NOT NULL, `created_by` CHAR(36) NULL, `updated_by` CHAR(36) NULL, `created_at` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), `updated_at` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), PRIMARY KEY (`id`), UNIQUE KEY `system_feature_flags_uuid_key` (`uuid`), UNIQUE KEY `system_feature_flags_key_environment_key` (`key`,`environment`), KEY `system_feature_flags_environment_enabled_idx` (`environment`,`enabled`)) ENGINE=InnoDB;
CREATE TABLE `system_import_profiles` (`id` BIGINT UNSIGNED NOT NULL AUTO_INCREMENT, `uuid` CHAR(36) NOT NULL, `name` VARCHAR(160) NOT NULL, `entity` VARCHAR(80) NOT NULL, `version` INT NOT NULL DEFAULT 1, `format` VARCHAR(8) NOT NULL, `column_mapping` JSON NOT NULL, `field_mapping` JSON NOT NULL, `conflict_strategy` VARCHAR(32) NOT NULL, `transaction_strategy` VARCHAR(32) NOT NULL, `active` BOOLEAN NOT NULL DEFAULT false, `created_by` CHAR(36) NOT NULL, `updated_by` CHAR(36) NOT NULL, `created_at` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), `updated_at` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), PRIMARY KEY (`id`), UNIQUE KEY `system_import_profiles_uuid_key` (`uuid`), UNIQUE KEY `system_import_profiles_name_version_key` (`name`,`version`), KEY `system_import_profiles_entity_active_idx` (`entity`,`active`)) ENGINE=InnoDB;
CREATE TABLE `system_integration_credentials` (`id` BIGINT UNSIGNED NOT NULL AUTO_INCREMENT, `uuid` CHAR(36) NOT NULL, `integration_id` BIGINT UNSIGNED NOT NULL, `credential_type` VARCHAR(32) NOT NULL, `secret_ref` VARCHAR(255) NOT NULL, `version` INT NOT NULL DEFAULT 1, `status` VARCHAR(16) NOT NULL, `issued_at` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), `access_token_expires_at` DATETIME(3) NULL, `refresh_token_expires_at` DATETIME(3) NULL, `rotated_at` DATETIME(3) NULL, `revoked_at` DATETIME(3) NULL, `metadata` JSON NOT NULL, `created_at` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), `updated_at` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), PRIMARY KEY (`id`), UNIQUE KEY `system_integration_credentials_uuid_key` (`uuid`), UNIQUE KEY `system_integration_credentials_type_version_key` (`integration_id`,`credential_type`,`version`), KEY `system_integration_credentials_expiry_idx` (`access_token_expires_at`)) ENGINE=InnoDB;
CREATE TABLE `system_integration_runtime` (`id` BIGINT UNSIGNED NOT NULL AUTO_INCREMENT, `uuid` CHAR(36) NOT NULL, `integration_id` BIGINT UNSIGNED NOT NULL, `circuit_state` VARCHAR(16) NOT NULL DEFAULT 'CLOSED', `failure_count` INT NOT NULL DEFAULT 0, `success_count` INT NOT NULL DEFAULT 0, `opened_at` DATETIME(3) NULL, `half_open_at` DATETIME(3) NULL, `next_retry_at` DATETIME(3) NULL, `sync_direction` VARCHAR(24) NOT NULL DEFAULT 'BIDIRECTIONAL', `sync_cursor` VARCHAR(255) NULL, `last_synced_at` DATETIME(3) NULL, `request_mapping` JSON NOT NULL, `response_mapping` JSON NOT NULL, `last_health_at` DATETIME(3) NULL, `last_operation_at` DATETIME(3) NULL, `last_operation_status` VARCHAR(24) NULL, `metadata` JSON NOT NULL, `created_at` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), `updated_at` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), PRIMARY KEY (`id`), UNIQUE KEY `system_integration_runtime_uuid_key` (`uuid`), UNIQUE KEY `system_integration_runtime_integration_key` (`integration_id`), KEY `system_integration_runtime_circuit_idx` (`circuit_state`,`next_retry_at`)) ENGINE=InnoDB;
CREATE TABLE `system_integration_operations` (`id` BIGINT UNSIGNED NOT NULL AUTO_INCREMENT, `uuid` CHAR(36) NOT NULL, `integration_id` BIGINT UNSIGNED NOT NULL, `operation_key` VARCHAR(120) NOT NULL, `direction` VARCHAR(24) NOT NULL, `idempotency_key` VARCHAR(180) NOT NULL, `attempt` INT NOT NULL DEFAULT 0, `max_attempts` INT NOT NULL DEFAULT 3, `state` VARCHAR(24) NOT NULL, `request_hash` CHAR(64) NULL, `response_hash` CHAR(64) NULL, `request_payload` JSON NULL, `response_payload` JSON NULL, `next_attempt_at` DATETIME(3) NULL, `started_at` DATETIME(3) NULL, `completed_at` DATETIME(3) NULL, `error_code` VARCHAR(80) NULL, `error_message` VARCHAR(500) NULL, `metadata` JSON NOT NULL, `created_at` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), `updated_at` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), PRIMARY KEY (`id`), UNIQUE KEY `system_integration_operations_uuid_key` (`uuid`), UNIQUE KEY `system_integration_operations_idempotency_key` (`integration_id`,`idempotency_key`), KEY `system_integration_operations_state_idx` (`integration_id`,`state`,`next_attempt_at`)) ENGINE=InnoDB;
CREATE TABLE `system_integration_events` (`id` BIGINT UNSIGNED NOT NULL AUTO_INCREMENT, `uuid` CHAR(36) NOT NULL, `integration_id` BIGINT UNSIGNED NOT NULL, `event_key` VARCHAR(180) NOT NULL, `event_name` VARCHAR(120) NOT NULL, `event_version` INT NOT NULL DEFAULT 1, `payload` JSON NOT NULL, `payload_hash` CHAR(64) NOT NULL, `idempotency_key` VARCHAR(180) NULL, `status` VARCHAR(24) NOT NULL, `occurred_at` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), `processed_at` DATETIME(3) NULL, `created_at` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), PRIMARY KEY (`id`), UNIQUE KEY `system_integration_events_uuid_key` (`uuid`), UNIQUE KEY `system_integration_events_event_key` (`integration_id`,`event_key`), KEY `system_integration_events_status_idx` (`integration_id`,`status`,`occurred_at`)) ENGINE=InnoDB;
CREATE TABLE `system_integration_conflicts` (`id` BIGINT UNSIGNED NOT NULL AUTO_INCREMENT, `uuid` CHAR(36) NOT NULL, `integration_id` BIGINT UNSIGNED NOT NULL, `operation_uuid` CHAR(36) NULL, `conflict_key` VARCHAR(180) NOT NULL, `entity_type` VARCHAR(80) NOT NULL, `local_version` VARCHAR(80) NULL, `remote_version` VARCHAR(80) NULL, `resolution` VARCHAR(32) NOT NULL, `status` VARCHAR(24) NOT NULL, `local_payload` JSON NULL, `remote_payload` JSON NULL, `resolved_by` CHAR(36) NULL, `resolved_at` DATETIME(3) NULL, `created_at` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), `updated_at` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), PRIMARY KEY (`id`), UNIQUE KEY `system_integration_conflicts_uuid_key` (`uuid`), UNIQUE KEY `system_integration_conflicts_conflict_key` (`integration_id`,`conflict_key`)) ENGINE=InnoDB;
CREATE TABLE `system_operational_alerts` (`id` BIGINT UNSIGNED NOT NULL AUTO_INCREMENT, `uuid` CHAR(36) NOT NULL, `alert_key` VARCHAR(160) NOT NULL, `severity` VARCHAR(16) NOT NULL, `status` VARCHAR(16) NOT NULL, `message` VARCHAR(500) NOT NULL, `dedupe_key` VARCHAR(220) NOT NULL, `resource_type` VARCHAR(80) NULL, `resource_uuid` CHAR(36) NULL, `metadata` JSON NOT NULL, `first_seen_at` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), `last_seen_at` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), `resolved_at` DATETIME(3) NULL, `created_at` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), `updated_at` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), PRIMARY KEY (`id`), UNIQUE KEY `system_operational_alerts_uuid_key` (`uuid`), UNIQUE KEY `system_operational_alerts_dedupe_key_key` (`dedupe_key`), KEY `system_operational_alerts_status_idx` (`status`,`severity`,`last_seen_at`)) ENGINE=InnoDB;
